const conteudo = $input.first().json.choices[0].message.content;
const dados = JSON.parse(conteudo);
return [{ json: { telefone: $('Extrair telefone e mensagem').first().json.telefone, itensPedidos: dados.itens ?? [] } }];

const produtos = $input.first().json.produtos;
const { telefone, itensPedidos } = $('Parsear resposta da IA').first().json;

function normalizar(t) {
  return t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

const itens = [];
const naoEncontrados = [];

for (const item of itensPedidos) {
  const alvo = normalizar(item.nome);
  const produto = produtos.find((p) => normalizar(p.nome).includes(alvo) || alvo.includes(normalizar(p.nome)));
  if (produto) {
    itens.push({ produto_id: produto.id, quantidade: item.quantidade });
  } else {
    naoEncontrados.push(item.nome);
  }
}

return [{ json: { telefone, itens, naoEncontrados } }];

